def sha256_stream_hex(stream, chunk_size=8192):
    start = stream.tell()
    digest = hashlib.sha256()
    try:
        for block in iter(lambda: stream.read(chunk_size), b''):
            digest.update(block)
        return digest.hexdigest()
    finally:
